tool_input.command:
cat >> test/orders.test.js <<'EOF'

const placedOrder = { net: 26905, shipping: { tier: "freight-express", cost: 5400 }, total: 34255 };

test("a damaged order refunds the full total", () => {
  assert.equal(refundFor(placedOrder, "damaged"), 34255);
});

test("a late order refunds the shipping cost", () => {
  assert.equal(refundFor(placedOrder, "late"), 5400);
});

test("a changed-mind order refunds the net minus a 10% restocking fee, rounded to the cent", () => {
  assert.equal(refundFor(placedOrder, "changed-mind"), 26905 - 2691);
});

test("an unrecognised reason refunds nothing", () => {
  assert.equal(refundFor(placedOrder, "whim"), 0);
});
EOF
npm run coverage 2>&1 | tail -30; grep -n "orders\|refund" README.md
